        "code": {
          "text": "Hand pain"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Pain in DIP and PIP joints, worse after gardening or tablet use."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Hand joint appearance"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Visible bony DIP swellings consistent with Heberden's nodes; no obvious erythema visible by video."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Systemic symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No fevers, weight loss, or night sweats reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Function and activity"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Activities of daily living remain intact. Reduced long walks and avoids stairs; continues gardening in shorter sessions."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
