      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Knee examination by video"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No obvious knee deformity or large effusion visible by video."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Bilateral knee X-ray"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "X-ray reviewed, obtained approximately one week before the encounter: mild to moderate tricompartmental osteoarthritis, medial greater than lateral, with joint-space narrowing and small osteophytes. No fracture, chondrocalcinosis, or large effusion."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Hand X-ray"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "PA hand X-ray shows DIP/PIP osteoarthritis with osteophytes and joint-space narrowing, especially in the bilateral index and middle fingers; early mild first CMC osteoarthritis with mild joint-space narrowing and small osteophytes. No erosions or inflammatory features."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Full blood examination"
